   -> linking to ${brokenLinks
     .map((brokenLink) => this.brokenLinkMessage(brokenLink))
     .join('\n   -> linking to ')}`
        : '';

    return `${anchorMessage}`;
  }

  createBrokenAnchorsMessage(
    brokenAnchors: BrokenLinksMap,
  ): string | undefined {
    this.brokenByPage = brokenAnchors;
    if (Object.keys(this.brokenByPage).length === 0) {
      return undefined;
    }

    const message = `Docusaurus found broken anchors!

