    this.createBrokenLinksMessage(pagePath, brokenLinks),
  )
  .join('\n')}
`;
    this.reportMessages.push(message);
    return message;
  }

  createBrokenPathsMessage(
    brokenPathsMap: BrokenLinksMap,
  ): string | undefined {
    this.brokenByPage = brokenPathsMap;
    if (Object.keys(this.brokenByPage).length === 0) {
      return undefined;
